signals.use:
ui.Opened:Connect(function()
    print("Opened")
end)

ui.Closed:Connect(function()
    print("Closed")
end)

ui.KeyChanged:Connect(function(key)
    print(key)
end)

ui.ThemeChanged:Connect(function(name)
    print(name)
end)

ui.ScreenChanged:Connect(function(width, height)
    print(width, height)
end)

game.Players.CharacterAdded:Connect(function(character)
    print(character)
end)

game.Players.CharacterRemoved:Connect(function(character)
    print(character)
end)

game.Creatures.Added:Connect(function(creature)
    print(creature)
end)

game.Creatures.Removed:Connect(function(creature, info)
    print(creature, info)
end)

game.Creatures.Died:Connect(function(creature, info)
    print(creature, info)
end)

game.Creatures.Cleared:Connect(function()
    print("Cleared")
end)

game.MapChanged:Connect(function(name)
    print(name)
end)

game.Research.Changed:Connect(function(level, points)
    print(level, points)
end)

game.Data.Changed:Connect(function(name)
    print(name)
end)
